package dash.web;

import dash.Dash;
import dash.StatsCollector;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Locale;

public final class GraphsPage {
    private GraphsPage() { }

    public static String render() {
        String json = Dash.getStatsCollector() == null ? "[]" : Dash.getStatsCollector().getHistoryJson();
        snapshot(json);
        StatsCollector.StatsSample sample = Dash.getStatsCollector() == null ? null : Dash.getStatsCollector().getLatest();
        String content = HtmlTemplate.statsHeader() + styles()
                + "<main class='graph-main flex-1 min-w-0 p-4 sm:p-6'><div class='max-w-7xl mx-auto space-y-4'>"
                + "<header class='graph-header'><div><span class='graph-kicker'><span class='material-symbols-outlined'>query_stats</span>Telemetry</span>"
                + "<h1>Server Graphs</h1><p>Live performance, stable ranges and portable metric snapshots.</p></div>"
                + "<div class='graph-actions'><div class='graph-ranges' role='group' aria-label='Time range'>"
                + range("1h", true) + range("6h", false) + range("24h", false) + range("7d", false)
                + "</div><button id='graph-live' class='graph-btn is-live' title='Pause live updates'><span class='material-symbols-outlined'>pause</span><b>Live</b></button>"
                + "<button id='graph-json' class='graph-icon' title='Export JSON'><span class='material-symbols-outlined'>data_object</span></button>"
                + "<button id='graph-csv' class='graph-icon' title='Export CSV'><span class='material-symbols-outlined'>table_view</span></button></div></header>"
                + "<section class='graph-metrics'>" + metric("TPS", number(sample == null ? null : sample.tps, "%.2f"), "graph-tps")
                + metric("MSPT", number(sample == null ? null : sample.mspt, "%.1f"), "graph-mspt")
                + metric("CPU", number(sample == null ? null : sample.cpuUsage, "%.1f") + (sample == null ? "" : "%"), "graph-cpu")
                + metric("RAM", sample == null ? "--" : sample.ramUsed + " / " + sample.ramMax + " MB", "graph-ram") + "</section>"
                + "<div id='graph-empty' class='graph-empty hidden'><span class='material-symbols-outlined'>monitoring</span><b>No samples in this range</b><small>Dash will draw the chart as telemetry arrives.</small></div>"
                + "<section class='graph-grid'>" + chart("tpsChart", "TPS", "Target 20") + chart("ramChart", "RAM", "MB")
                + chart("cpuChart", "CPU", "Percent") + chart("msptChart", "MSPT", "Lower is better") + "</section>"
                + "</div></main>" + HtmlTemplate.statsScript() + script(json);
        return HtmlTemplate.page("Graphs", "/graphs", content);
    }

    private static String number(Double value, String format) { return value == null ? "--" : String.format(Locale.ROOT, format, value); }
    private static String range(String value, boolean active) { return "<button data-range='" + value + "' class='" + (active ? "is-active" : "") + "'>" + value + "</button>"; }
    private static String metric(String label, String value, String id) { return "<article><small>" + label + "</small><b id='" + id + "'>" + value + "</b></article>"; }
    private static String chart(String id, String title, String detail) { return "<article class='graph-card'><header><b>" + title + "</b><small>" + detail + "</small></header><div class='graph-canvas'><canvas id='" + id + "' tabindex='0' aria-label='" + title + " history'></canvas><div class='graph-tooltip hidden' role='status'></div></div><footer class='graph-time-axis flex items-center justify-between border-t border-white/5 px-3 py-2 text-[10px] font-mono text-slate-500'><time data-graph-start>--</time><time data-graph-end>--</time></footer></article>"; }

    private static void snapshot(String json) {
        try {
            Path file = Dash.getInstance().getDataFolder().toPath().resolve("server-graphs.json");
            Files.createDirectories(file.getParent());
            Files.writeString(file, json == null ? "[]" : json, StandardCharsets.UTF_8);
        } catch (Exception ignored) { }
    }

    private static String styles() {
        return "<style>.graph-main{color:#cbd5e1}.graph-header{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;border-bottom:1px solid rgba(100,116,139,.24);padding:.8rem 0 1rem}.graph-kicker{display:flex;align-items:center;gap:.35rem;font-size:.64rem;font-weight:800;text-transform:uppercase;color:#67e8f9}.graph-kicker span{font-size:17px}.graph-header h1{margin:.3rem 0 0;font-size:1.5rem;color:#f8fafc}.graph-header p{margin:.2rem 0 0;font-size:.72rem;color:#64748b}.graph-actions{display:flex;align-items:center;gap:.4rem}.graph-ranges{display:grid;grid-template-columns:repeat(4,1fr);overflow:hidden;border:1px solid rgba(100,116,139,.25);border-radius:7px}.graph-ranges button{border:0;border-right:1px solid rgba(100,116,139,.2);padding:.48rem .62rem;background:rgba(2,6,23,.3);font-size:.62rem;font-weight:800;color:#64748b}.graph-ranges button:last-child{border:0}.graph-ranges button.is-active{background:rgba(8,145,178,.14);color:#67e8f9}.graph-btn,.graph-icon{display:inline-flex;align-items:center;justify-content:center;gap:.3rem;height:34px;border:1px solid rgba(100,116,139,.28);border-radius:6px;background:rgba(2,6,23,.35);color:#94a3b8}.graph-btn{padding:0 .6rem;font-size:.62rem}.graph-btn span,.graph-icon span{font-size:17px}.graph-btn.is-live{color:#6ee7b7;border-color:rgba(16,185,129,.3)}.graph-icon{width:34px}.graph-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));overflow:hidden;border:1px solid rgba(100,116,139,.22);border-radius:7px;background:rgba(2,6,23,.26)}.graph-metrics article{padding:.75rem;border-right:1px solid rgba(100,116,139,.18)}.graph-metrics article:last-child{border:0}.graph-metrics small,.graph-metrics b{display:block}.graph-metrics small{font-size:.56rem;text-transform:uppercase;color:#64748b}.graph-metrics b{margin-top:.16rem;font-size:1rem;color:#e2e8f0}.graph-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem}.graph-card{min-width:0;border:1px solid rgba(100,116,139,.22);border-radius:7px;background:rgba(2,6,23,.28);overflow:hidden}.graph-card>header{display:flex;align-items:center;justify-content:space-between;padding:.7rem .8rem;border-bottom:1px solid rgba(100,116,139,.16)}.graph-card header b{font-size:.72rem;color:#e2e8f0}.graph-card header small{font-size:.57rem;color:#64748b}.graph-canvas{position:relative;height:270px}.graph-canvas canvas{width:100%;height:100%;display:block}.graph-tooltip{position:absolute;pointer-events:none;transform:translate(-50%,-110%);border:1px solid rgba(100,116,139,.35);border-radius:5px;background:#020617;padding:.35rem .45rem;font-size:.58rem;color:#cbd5e1;white-space:nowrap}.graph-empty{place-items:center;border:1px dashed rgba(100,116,139,.3);border-radius:7px;padding:2rem;color:#64748b}.graph-empty:not(.hidden){display:grid}.graph-empty span{font-size:28px}.graph-empty b,.graph-empty small{margin-top:.25rem}.hidden{display:none!important}@media(max-width:800px){.graph-header{align-items:flex-start;flex-direction:column}.graph-actions{width:100%;flex-wrap:wrap}.graph-ranges{flex:1}.graph-grid{grid-template-columns:1fr}.graph-metrics{grid-template-columns:repeat(2,1fr)}.graph-canvas{height:235px}}@media(prefers-reduced-motion:reduce){.graph-main *{animation:none!important;transition:none!important}}</style>";
    }

    private static String timestampScript(String json) {
        String safeJson = json == null || json.isBlank() ? "[]" : json;
        return "<script>(function(){let samples=" + safeJson + ",range='1h';const spans={\"1h\":36e5,\"6h\":216e5,\"24h\":864e5,\"7d\":6048e5};"
                + "function epoch(v){const n=Number(v||0);return n>0&&n<1e12?n*1000:n}function label(v){const d=new Date(epoch(v));return Number.isNaN(d.getTime())?'--':d.toLocaleString([],range==='7d'?{month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'}:{hour:'2-digit',minute:'2-digit',second:'2-digit'})}"
                + "function render(){const cutoff=Date.now()-spans[range],rows=(Array.isArray(samples)?samples:[]).filter(p=>epoch(p.t)>=cutoff).sort((a,b)=>epoch(a.t)-epoch(b.t)),start=rows[0],end=rows[rows.length-1];document.querySelectorAll('[data-graph-start]').forEach(e=>e.textContent=start?label(start.t):'--');document.querySelectorAll('[data-graph-end]').forEach(e=>e.textContent=end?label(end.t):'--')}"
                + "document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{range=b.dataset.range||'1h';render()}));async function refresh(){try{const r=await fetch('/api/stats/history',{credentials:'same-origin'});if(r.ok){const next=await r.json();if(Array.isArray(next))samples=next;render()}}catch(_){}}render();const timer=setInterval(refresh,5000);window.dashPageAbortController?.signal.addEventListener('abort',()=>clearInterval(timer),{once:true})})();</script>";
    }

    private static String script(String json) {
        return "<script>(function(){if(window.dashPageAbortController){try{window.dashPageAbortController.abort()}catch(_){}}const ctl=new AbortController();window.dashPageAbortController=ctl;let all=" + (json == null || json.isBlank() ? "[]" : json) + ",range='1h',live=true,timer=0,hover={};const epoch=v=>{const n=Number(v||0);return n>0&&n<1e12?n*1000:n},spans={\"1h\":36e5,\"6h\":216e5,\"24h\":864e5,\"7d\":6048e5},defs=[['tpsChart','tps','#22d3ee','TPS'],['ramChart','ram','#10b981','RAM'],['cpuChart','cpuUsage','#f59e0b','CPU'],['msptChart','mspt','#f43f5e','MSPT']];function data(){const cutoff=Date.now()-spans[range];return(Array.isArray(all)?all:[]).filter(p=>epoch(p.t)>=cutoff).sort((a,b)=>epoch(a.t)-epoch(b.t))}function val(p,k){return Number(p[k]??(k==='ram'?p.ramUsed:0)??0)}function draw(id,key,color,label){const c=document.getElementById(id),box=c.parentElement,d=data(),r=box.getBoundingClientRect(),w=Math.max(260,r.width),h=Math.max(200,r.height),q=devicePixelRatio||1;c.width=Math.round(w*q);c.height=Math.round(h*q);const x=c.getContext('2d');x.setTransform(q,0,0,q,0,0);x.clearRect(0,0,w,h);const p={l:38,r:16,t:20,b:25};x.strokeStyle='rgba(148,163,184,.11)';for(let i=0;i<5;i++){const y=p.t+(h-p.t-p.b)*i/4;x.beginPath();x.moveTo(p.l,y);x.lineTo(w-p.r,y);x.stroke()}if(!d.length)return;const vs=d.map(v=>val(v,key)),max=Math.max(key==='tps'?20:1,...vs),min=Math.min(0,...vs),span=Math.max(1,max-min),cutoff=Date.now()-spans[range],pts=d.map(v=>({x:p.l+(w-p.l-p.r)*Math.max(0,Math.min(1,(epoch(v.t)-cutoff)/spans[range])),y:h-p.b-(val(v,key)-min)/span*(h-p.t-p.b),v}));hover[id]={pts,key,label};const g=x.createLinearGradient(0,p.t,0,h-p.b);g.addColorStop(0,color+'4d');g.addColorStop(1,color+'02');x.beginPath();pts.forEach((v,i)=>i?x.lineTo(v.x,v.y):x.moveTo(v.x,v.y));x.lineTo(pts.at(-1).x,h-p.b);x.lineTo(pts[0].x,h-p.b);x.closePath();x.fillStyle=g;x.fill();x.beginPath();pts.forEach((v,i)=>i?x.lineTo(v.x,v.y):x.moveTo(v.x,v.y));x.strokeStyle=color;x.lineWidth=2;x.lineJoin='round';x.stroke()}function drawAll(){const d=data(),grid=document.querySelector('.graph-grid');document.getElementById('graph-empty').classList.toggle('hidden',d.length>0);grid.classList.toggle('hidden',!d.length);const start=d[0],end=d.at(-1),label=v=>v?new Date(epoch(v.t)).toLocaleString():'--';document.querySelectorAll('[data-graph-start]').forEach(e=>e.textContent=label(start));document.querySelectorAll('[data-graph-end]').forEach(e=>e.textContent=label(end));defs.forEach(v=>draw(...v));const p=all.at(-1);if(p){document.getElementById('graph-tps').textContent=val(p,'tps').toFixed(2);document.getElementById('graph-mspt').textContent=val(p,'mspt').toFixed(1);document.getElementById('graph-cpu').textContent=val(p,'cpuUsage').toFixed(1)+'%';document.getElementById('graph-ram').textContent=val(p,'ram')+' / '+Number(p.ramMax||0)+' MB'}}function tip(e,c){const s=hover[c.id],t=c.nextElementSibling;if(!s||!s.pts.length)return;const mx=e.clientX-c.getBoundingClientRect().left,p=s.pts.reduce((a,b)=>Math.abs(b.x-mx)<Math.abs(a.x-mx)?b:a);t.textContent=new Date(epoch(p.v.t)).toLocaleString()+' / '+s.label+': '+val(p.v,s.key).toFixed(2);t.style.left=p.x+'px';t.style.top=p.y+'px';t.classList.remove('hidden')}defs.forEach(d=>{const c=document.getElementById(d[0]);c.addEventListener('pointermove',e=>tip(e,c),{signal:ctl.signal});c.addEventListener('pointerleave',()=>c.nextElementSibling.classList.add('hidden'),{signal:ctl.signal})});document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{range=b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('is-active',x===b));refresh(true)},{signal:ctl.signal}));const liveBtn=document.getElementById('graph-live');liveBtn.addEventListener('click',()=>{live=!live;liveBtn.classList.toggle('is-live',live);liveBtn.querySelector('span').textContent=live?'pause':'play_arrow';liveBtn.querySelector('b').textContent=live?'Live':'Paused'},{signal:ctl.signal});async function refresh(force=false){if(!live&&!force)return;try{const r=await fetch('/api/stats/history?range='+encodeURIComponent(range),{signal:ctl.signal,credentials:'same-origin'});if(r.ok){const next=await r.json();if(Array.isArray(next))all=next;drawAll()}}catch(e){if(e.name!=='AbortError')liveBtn.querySelector('b').textContent='Offline'}}timer=setInterval(refresh,5000);ctl.signal.addEventListener('abort',()=>clearInterval(timer),{once:true});function download(type){const d=data(),keys=['t','tps','mspt','cpuUsage','ram','ramMax','ow','nether','end'];let text=type==='json'?JSON.stringify(d,null,2):keys.join(',')+'\\n'+d.map(p=>keys.map(k=>JSON.stringify(p[k]??'')).join(',')).join('\\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:type==='json'?'application/json':'text/csv'}));a.download='dash-metrics-'+range+'.'+type;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}document.getElementById('graph-json').onclick=()=>download('json');document.getElementById('graph-csv').onclick=()=>download('csv');let rz=0;addEventListener('resize',()=>{clearTimeout(rz);rz=setTimeout(drawAll,100)},{passive:true,signal:ctl.signal});requestAnimationFrame(drawAll)})();</script>";
    }
}
